--
-- Table structure for table `affiliate_order_items`
--

DROP TABLE IF EXISTS `affiliate_order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `affiliate_order_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` varchar(50) NOT NULL COMMENT 'Shopee order ID (ID đơn hàng)',
  `order_status` varchar(50) NOT NULL COMMENT 'Trạng thái đặt hàng',
  `checkout_id` varchar(30) NOT NULL COMMENT 'Checkout ID',
  `content_id` varchar(64) DEFAULT NULL COMMENT 'TikTok content/link tracking ID (RioHub content_id)',
  `ordered_at` datetime DEFAULT NULL COMMENT 'Thời Gian Đặt Hàng',
  `completed_at` datetime DEFAULT NULL COMMENT 'Thời gian hoàn thành',
  `clicked_at` datetime DEFAULT NULL COMMENT 'Thời gian Click',
  `shop_name` varchar(200) NOT NULL COMMENT 'Tên Shop',
  `shop_id` bigint(20) unsigned NOT NULL COMMENT 'Shop ID',
  `shop_type` varchar(50) DEFAULT NULL COMMENT 'Loại Shop (Shopee Mall, Preferred, etc.)',
  `item_id` bigint(20) unsigned DEFAULT NULL,
  `item_name` varchar(500) NOT NULL COMMENT 'Tên Item',
  `model_id` bigint(20) unsigned NOT NULL COMMENT 'ID Model (SKU)',
  `product_type` varchar(50) DEFAULT NULL COMMENT 'Loại sản phẩm (Normal Product, etc.)',
  `promotion_id` varchar(50) DEFAULT NULL COMMENT 'Promotion ID',
  `category_l1` varchar(100) DEFAULT NULL COMMENT 'L1 Danh mục toàn cầu',
  `category_l2` varchar(100) DEFAULT NULL COMMENT 'L2 Danh mục toàn cầu',
  `category_l3` varchar(100) DEFAULT NULL COMMENT 'L3 Danh mục toàn cầu',
  `item_price` decimal(16,2) NOT NULL COMMENT 'Giá (₫)',
  `quantity` int(11) NOT NULL COMMENT 'Số lượng',
  `order_amount` decimal(16,2) NOT NULL COMMENT 'Giá trị đơn hàng (₫)',
  `refund_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Số tiền hoàn trả (₫)',
  `commission_type` varchar(30) NOT NULL COMMENT 'Loại Hoa hồng (Shopee Comm / XTRA Comm)',
  `campaign_partner` varchar(200) DEFAULT NULL COMMENT 'Đối tác chiến dịch',
  `shopee_commission_rate` decimal(5,2) NOT NULL COMMENT 'Tỷ lệ hoa hồng Shopee (%)',
  `shopee_commission` decimal(16,2) NOT NULL COMMENT 'Hoa hồng Shopee trên sản phẩm (₫)',
  `seller_commission_rate` decimal(5,2) NOT NULL COMMENT 'Tỷ lệ hoa hồng người bán (%)',
  `xtra_commission` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Hoa hồng Xtra trên sản phẩm (₫)',
  `total_product_commission` decimal(16,2) NOT NULL COMMENT 'Tổng hoa hồng sản phẩm (₫)',
  `order_commission_shopee` decimal(16,2) NOT NULL COMMENT 'Hoa hồng đơn hàng từ Shopee (₫)',
  `order_commission_seller` decimal(16,2) NOT NULL COMMENT 'Hoa hồng đơn hàng từ Người bán (₫)',
  `total_order_commission` decimal(16,2) NOT NULL COMMENT 'Tổng hoa hồng đơn hàng (₫)',
  `mcn_name` varchar(200) DEFAULT NULL COMMENT 'Tên MNC/MCN đã liên kết',
  `mcn_contract_code` varchar(100) DEFAULT NULL COMMENT 'Mã hợp đồng MCN',
  `mcn_management_fee_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'Mức phí quản lý MCN (%)',
  `mcn_management_fee` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Phí quản lý MCN (₫)',
  `agreed_commission_rate` decimal(5,2) NOT NULL COMMENT 'Mức hoa hồng tiếp thị liên kết theo thỏa thuận (%)',
  `net_commission` decimal(16,2) NOT NULL COMMENT 'Hoa hồng ròng tiếp thị liên kết (₫)',
  `affiliate_status` varchar(50) NOT NULL COMMENT 'Trạng thái sản phẩm liên kết',
  `product_note` text DEFAULT NULL COMMENT 'Ghi chú sản phẩm',
  `attribute_type` varchar(100) DEFAULT NULL COMMENT 'Loại thuộc tính',
  `buyer_status` varchar(50) DEFAULT NULL COMMENT 'Trạng thái người mua',
  `sub_id1` varchar(100) DEFAULT NULL COMMENT 'Sub ID 1',
  `sub_id2` varchar(100) DEFAULT NULL COMMENT 'Sub ID 2',
  `sub_id3` varchar(100) DEFAULT NULL COMMENT 'Sub ID 3',
  `sub_id4` varchar(100) DEFAULT NULL COMMENT 'Sub ID 4',
  `sub_id5` varchar(100) DEFAULT NULL COMMENT 'Sub ID 5',
  `channel` varchar(50) DEFAULT NULL COMMENT 'Kênh (Facebook, Websites, etc.)',
  `platform` varchar(30) NOT NULL DEFAULT 'Shopee',
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `cashback_rate` decimal(5,2) DEFAULT NULL COMMENT 'Tỷ lệ cashback (50/60/70)',
  `cashback_amount` decimal(16,2) DEFAULT NULL COMMENT 'Tiền user thực nhận',
  `import_batch` varchar(20) NOT NULL COMMENT 'Mã lần import (Ymd_His)',
  `source_file` varchar(255) DEFAULT NULL COMMENT 'Tên file CSV gốc',
  `first_imported_at` datetime DEFAULT NULL COMMENT 'Lần đầu xuất hiện trong hệ thống',
  `last_shopee_sync_at` datetime DEFAULT NULL COMMENT 'Lần cuối đồng bộ từ Shopee',
  `last_tiktok_sync_at` datetime DEFAULT NULL COMMENT 'Lần cuối đồng bộ từ TikTok/RioHub',
  `locked_at` datetime DEFAULT NULL COMMENT 'Thời điểm khóa (đơn hoàn thành, không sync nữa)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `last_shopeefood_sync_at` datetime DEFAULT NULL COMMENT 'Lần cuối đồng bộ từ ShopeeFood',
  `shopee_food_line_key` varchar(120) DEFAULT NULL COMMENT 'Khóa dòng ShopeeFood: checkout_id:promotion_id (chỉ điền cho platform=ShopeeFood)',
  `lazada_line_key` varchar(160) DEFAULT NULL COMMENT 'Khóa dòng Lazada: orderId:subOrderId:sku (chỉ điền cho platform=Lazada)',
  `last_lazada_sync_at` datetime DEFAULT NULL COMMENT 'Lần cuối đồng bộ từ Lazada',
  `delivered_at` datetime DEFAULT NULL COMMENT 'Thời điểm giao hàng RAW deliveredTime (Lazada) — NULL thì không finalize',
  `finalized_at` datetime DEFAULT NULL COMMENT 'Thời điểm chốt (LOCK): cashback coi như frozen',
  `finalize_gate` varchar(40) DEFAULT NULL COMMENT 'Rule dùng để LOCK: tiktok_settled | lazada_delivered_10d',
  `final_cashback_amount` decimal(16,2) DEFAULT NULL COMMENT 'Cashback đã đóng băng = số tiền thực credit lúc LOCK',
  `reversed_at` datetime DEFAULT NULL COMMENT 'Thời điểm reversal hợp lệ (returned/cancelled sau LOCK)',
  `tt_order_status` smallint(5) unsigned DEFAULT NULL COMMENT 'Raw tt_order_status RioHub (100/103/104) — TikTok',
  `settled_at` datetime DEFAULT NULL COMMENT 'Raw settled_at RioHub (informational; có thể NULL trên SETTLED hợp lệ)',
  `lazada_raw_status` varchar(100) DEFAULT NULL COMMENT 'Raw Lazada conversion status (fulfilled/delivered/returned/rejected/cancelled/...)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_platform_order_item` (`platform`,`order_id`,`item_id`),
  UNIQUE KEY `uk_shopeefood_item_key` (`platform`,`shopee_food_line_key`),
  UNIQUE KEY `uk_lazada_line_key` (`platform`,`lazada_line_key`),
  KEY `affiliate_order_items_username_index` (`username`),
  KEY `affiliate_order_items_user_id_index` (`user_id`),
