--
-- Table structure for table `wallet_transactions`
--

DROP TABLE IF EXISTS `wallet_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `running_no` varchar(30) NOT NULL COMMENT 'Mã giao dịch (WT + ngày + số thứ tự)',
  `user_id` bigint(20) unsigned NOT NULL,
  `username` varchar(100) NOT NULL,
  `platform` varchar(30) DEFAULT NULL,
  `type` enum('cashback','withdraw','promotion','bonus','referral','adjustment','refund') NOT NULL,
  `direction` enum('credit','debit') NOT NULL,
  `amount` decimal(16,2) NOT NULL,
  `balance_before` decimal(16,2) DEFAULT NULL,
  `balance_after` decimal(16,2) DEFAULT NULL,
  `reference_type` varchar(50) NOT NULL,
  `reference_id` bigint(20) unsigned DEFAULT NULL,
  `description` varchar(255) NOT NULL,
  `status` enum('pending','completed','cancelled','failed') NOT NULL DEFAULT 'completed',
  `completed_at` datetime DEFAULT NULL COMMENT 'Thời điểm transaction hoàn tất (khác created_at)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `note` text DEFAULT NULL,
  `processed_by` bigint(20) unsigned DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu mở rộng (order_id, bank, account_number, ...)' CHECK (json_valid(`metadata`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `wallet_transactions_running_no_unique` (`running_no`),
  UNIQUE KEY `wallet_transactions_ref_unique` (`reference_type`,`reference_id`,`type`),
  KEY `wallet_transactions_username_index` (`username`),
  KEY `wallet_transactions_processed_by_foreign` (`processed_by`),
  KEY `wallet_transactions_created_at_index` (`created_at`),
  KEY `wallet_transactions_reference_type_reference_id_index` (`reference_type`,`reference_id`),
  KEY `wallet_transactions_platform_index` (`platform`),
  KEY `wallet_transactions_type_index` (`type`),
  KEY `wallet_transactions_reference_id_index` (`reference_id`),
  KEY `wallet_transactions_status_index` (`status`),
  KEY `wallet_transactions_user_id_status_index` (`user_id`,`status`),
  KEY `wallet_transactions_user_id_direction_status_index` (`user_id`,`direction`,`status`),
  CONSTRAINT `wallet_transactions_processed_by_foreign` FOREIGN KEY (`processed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `wallet_transactions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1049 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

