--
-- Table structure for table `withdraw_requests`
--

DROP TABLE IF EXISTS `withdraw_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `withdraw_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `running_no` varchar(30) NOT NULL COMMENT 'Mã yêu cầu rút tiền (WR + YYYYMMDD + 4 số thứ tự)',
  `user_id` bigint(20) unsigned NOT NULL,
  `username` varchar(100) NOT NULL,
  `amount` decimal(16,2) NOT NULL,
  `bank_name` varchar(100) NOT NULL,
  `bank_account` varchar(50) NOT NULL,
  `account_name` varchar(150) NOT NULL,
  `status` enum('pending','approved','paid','rejected','cancelled') NOT NULL DEFAULT 'pending',
  `processed_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `note` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu mở rộng (bank_code, ip, ...)' CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `withdraw_requests_running_no_unique` (`running_no`),
  KEY `withdraw_requests_username_index` (`username`),
  KEY `withdraw_requests_processed_by_user_id_foreign` (`processed_by_user_id`),
  KEY `withdraw_requests_running_no_index` (`running_no`),
  KEY `withdraw_requests_user_id_index` (`user_id`),
  KEY `withdraw_requests_created_at_index` (`created_at`),
  KEY `withdraw_requests_status_index` (`status`),
  KEY `withdraw_requests_user_id_status_index` (`user_id`,`status`),
  CONSTRAINT `withdraw_requests_processed_by_user_id_foreign` FOREIGN KEY (`processed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `withdraw_requests_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

